const balances = new Map([["naive", 0], ["idempotent", 0]]);
const processed = new Set<string>();

function naive(points: number): void {
  balances.set("naive", balances.get("naive")! + points);
}

function idempotent(messageId: string, points: number): void {
  if (processed.has(messageId)) return;
  processed.add(messageId);
  balances.set("idempotent", balances.get("idempotent")! + points);
}

