const jobs = [
  { id: "update-price-1", failuresLeft: 0, runAt: 0 },
  { id: "update-price-2", failuresLeft: 1, runAt: 0 },
  { id: "update-price-3", failuresLeft: 0, runAt: 0 },
];
const finished: string[] = [];

for (let now = 0; now <= 3_000; now += 1_000) {
  for (const job of jobs) {
    if (job.runAt !== now || finished.includes(job.id)) continue;
    if (job.failuresLeft > 0) {
      job.failuresLeft -= 1;
      job.runAt = now + 2_000;
    } else {
      finished.push(job.id);
    }
  }
}
