import { PGlite } from "@electric-sql/pglite";

const db = new PGlite();
await db.exec(`CREATE TABLE outbox (id serial PRIMARY KEY, payload text NOT NULL, sent_at timestamptz);
  INSERT INTO outbox (payload) VALUES ('receipt 1001'), ('receipt 1002');`);

let queueUp = false;
async function relay(): Promise<string> {
  try {
    return await db.transaction(async (tx) => {
      const { rows } = await tx.query<{ id: number }>("SELECT id FROM outbox WHERE sent_at IS NULL FOR UPDATE SKIP LOCKED");
      await tx.query("UPDATE outbox SET sent_at = now() WHERE id = ANY($1)", [rows.map((row) => row.id)]);
      if (!queueUp) throw new Error("queue unreachable");
      return `published ${rows.length}`;
    });
  } catch (error) {
    return error instanceof Error ? error.message : "error";
  }
}

const unsent = async () => (await db.query<{ n: number }>("SELECT count(*)::int AS n FROM outbox WHERE sent_at IS NULL")).rows[0]?.n;
console.log(await relay(), "- unsent:", await unsent());
queueUp = true;
console.log(await relay(), "- unsent:", await unsent());
await db.close();

