const MAX_ATTEMPTS = 3;
const now = 10_000;
const dead: string[] = [];

interface Job { id: string; attempts: number; runAt: number; lastError?: string }

function fail(job: Job, error: string, permanent: boolean): "retry" | "dead" {
  job.lastError = error;
  if (permanent || job.attempts >= MAX_ATTEMPTS) {
    dead.push(job.id);
    return "dead";
  }
  job.runAt = now + 1_000 * 2 ** (job.attempts - 1);
  return "retry";
}

const flaky: Job = { id: "job-1", attempts: 2, runAt: 0 };
const exhausted: Job = { id: "job-2", attempts: 3, runAt: 0 };
const invalid: Job = { id: "job-3", attempts: 1, runAt: 0 };
console.log(fail(flaky, "503", false), flaky.runAt);
console.log(fail(exhausted, "503", false), fail(invalid, "bad e-mail", true), dead);

