interface Job { id: string; attempts: number; runAt: number; leasedUntil: number }

const jobs: Job[] = [
  { id: "job-1", attempts: 1, runAt: 5_000, leasedUntil: 0 },
  { id: "job-2", attempts: 0, runAt: 0, leasedUntil: 0 },
];

function claim(now: number): Job | undefined {
  const job = jobs.find((candidate) => candidate.runAt <= now && candidate.leasedUntil <= now);
  if (job === undefined) return undefined;
  job.attempts += 1;
  job.leasedUntil = now + 30_000;
  return job;
}

const first = claim(1_000);
const second = claim(1_000);
const third = claim(6_000);
