interface Row { id: number; payload: string; sentAt: number | null }

const outbox: Row[] = [
  { id: 1, payload: "receipt 1001", sentAt: 5 },
  { id: 2, payload: "receipt 1002", sentAt: null },
  { id: 3, payload: "receipt 1003", sentAt: null },
];

function relay(publish: (jobId: string, payload: string) => void, now: number): number {
  let count = 0;
  for (const row of outbox) {
    if (row.sentAt !== null) continue;
    publish(`outbox-${row.id}`, row.payload);
    row.sentAt = now;
    count += 1;
  }
  return count;
}

const published: string[] = [];
console.log(relay((jobId) => published.push(jobId), 10), published, outbox.map((row) => row.sentAt));

